<?php if ($pagination['pages'] > 1): ?><nav class="pagination-bar" aria-label="Paginação"><span>Página <?= $pagination['page'] ?> de <?= $pagination['pages'] ?></span><div class="d-flex gap-2"><?php if ($pagination['page'] > 1): ?><a class="btn btn-sm btn-outline-secondary" href="<?= e(url(array_merge($paginationParams,['p'=>$pagination['page']-1]))) ?>">Anterior</a><?php endif; ?><?php if ($pagination['page'] < $pagination['pages']): ?><a class="btn btn-sm btn-outline-primary" href="<?= e(url(array_merge($paginationParams,['p'=>$pagination['page']+1]))) ?>">Próxima</a><?php endif; ?></div></nav><?php endif; ?>
